/**
 * A/B LLM eval for AST parsing experiment.
 *
 * Compares agent task performance using context generated by:
 * - main (regex-based parsing)  -> /tmp/clarte-main-claude.md
 * - AST branch (tree-sitter)    -> /tmp/clarte-ast-claude.md
 *
 * Tracks: pass/fail, input/output tokens, cost, context size.
 *
 * Skipped unless LLM_EVAL=1 and ANTHROPIC_API_KEY are set.
 *
 * Run:   LLM_EVAL=1 npx vitest run src/__tests__/eval/ast-quick-eval.test.ts
 * Quick: LLM_EVAL=1 N_ITERS=1 npx vitest run src/__tests__/eval/ast-quick-eval.test.ts
 */

import { describe, it, expect, beforeAll } from "vitest";
import Anthropic from "@anthropic-ai/sdk";
import { readFileSync } from "node:fs";

const SKIP = !process.env.LLM_EVAL || !process.env.ANTHROPIC_API_KEY;
const N_ITERS = parseInt(process.env.N_ITERS ?? "2", 10);
const MODEL = "claude-sonnet-4-6";
const TEMPERATURE = 0;

// Sonnet pricing (per million tokens)
const COST_PER_M_INPUT = 3.0;
const COST_PER_M_OUTPUT = 15.0;

// ── Tasks ────────────────────────────────────────────────────────────────────

interface EvalTask {
  id: string;
  category: string;
  question: string;
  /** Deterministic check: all keywords must appear in the answer */
  requiredKeywords?: string[];
  /** LLM judge prompt (for open-ended tasks) */
  judgePrompt?: string;
}

const TASKS: EvalTask[] = [
  {
    id: "file-1",
    category: "file-location",
    question: "Which file contains the buildImportGraph function?",
    requiredKeywords: ["graph.ts"],
  },
  {
    id: "file-2",
    category: "file-location",
    question: "Which file handles the code snapshot generation? Name the file path.",
    requiredKeywords: ["snapshot.ts"],
  },
  {
    id: "dep-1",
    category: "dependency",
    question: "What are the top 3 most imported files in the clarte codebase? List them by import count.",
    requiredKeywords: ["types.ts", "utils.ts", "graph.ts"],
  },
  {
    id: "dep-2",
    category: "dependency",
    question: "Which files form tight couplings (many imported names)? Name at least two pairs.",
    requiredKeywords: ["graph.ts", "types.ts"],
  },
  {
    id: "type-1",
    category: "type-understanding",
    question: "What fields does the ImportGraph type/interface have? List at least 4.",
    requiredKeywords: ["edges", "files"],
  },
  {
    id: "type-2",
    category: "type-understanding",
    question: "What categories can a SnapshotEntry have? List them all.",
    requiredKeywords: ["type", "interface", "function", "component", "hook"],
  },
  {
    id: "arch-1",
    category: "architecture",
    question: "What are the architectural chokepoints in the clarte codebase? Name the top 3 files.",
    requiredKeywords: ["types.ts", "graph.ts", "utils.ts"],
  },
  {
    id: "arch-2",
    category: "architecture",
    question: "Which file is the most unstable (frequently changing) orchestrator?",
    requiredKeywords: ["index.ts"],
  },
  {
    id: "mod-1",
    category: "modification",
    question: "If I wanted to add support for a new programming language (e.g., Kotlin) to clarte, which files would I need to modify? Explain your reasoning.",
    judgePrompt: `Score 1 if the answer mentions at least 3 of these files: graph.ts, snapshot.ts, types.ts, detect.ts, ast-parse.ts. Score 0 otherwise. Reply with just "1" or "0".`,
  },
  {
    id: "mod-2",
    category: "modification",
    question: "What test files should I run after modifying graph.ts? List at least 5.",
    requiredKeywords: ["graph.test.ts"],
  },
];

// ── Types ────────────────────────────────────────────────────────────────────

interface CallResult {
  answer: string;
  passed: boolean;
  inputTokens: number;
  outputTokens: number;
}

interface TaskResult {
  taskId: string;
  category: string;
  iteration: number;
  main: CallResult;
  ast: CallResult;
}

// ── Helpers ──────────────────────────────────────────────────────────────────

let client: Anthropic;
let mainContext: string;
let astContext: string;

function checkKeywords(answer: string, keywords: string[]): boolean {
  const lower = answer.toLowerCase();
  return keywords.every((kw) => lower.includes(kw.toLowerCase()));
}

function estimateTokens(text: string): number {
  return Math.ceil(text.length / 3.2);
}

function costFromTokens(input: number, output: number): number {
  return (input / 1_000_000) * COST_PER_M_INPUT + (output / 1_000_000) * COST_PER_M_OUTPUT;
}

async function askWithContext(
  context: string,
  question: string,
): Promise<{ answer: string; inputTokens: number; outputTokens: number }> {
  const response = await client.messages.create({
    model: MODEL,
    max_tokens: 1024,
    temperature: TEMPERATURE,
    messages: [
      {
        role: "user",
        content:
          `You are an expert developer analyzing a codebase. Here is the project's CLAUDE.md context file:\n\n<context>\n${context}\n</context>\n\nAnswer this question concisely:\n${question}`,
      },
    ],
  });

  const block = response.content[0];
  const answer = block.type === "text" ? block.text : "";
  return {
    answer,
    inputTokens: response.usage.input_tokens,
    outputTokens: response.usage.output_tokens,
  };
}

async function judgeAnswer(
  answer: string,
  judgePrompt: string,
): Promise<{ passed: boolean; inputTokens: number; outputTokens: number }> {
  const response = await client.messages.create({
    model: MODEL,
    max_tokens: 10,
    temperature: 0,
    messages: [
      {
        role: "user",
        content: `Here is an answer to evaluate:\n\n<answer>\n${answer}\n</answer>\n\n${judgePrompt}`,
      },
    ],
  });

  const block = response.content[0];
  const passed = block.type === "text" && block.text.trim() === "1";
  return {
    passed,
    inputTokens: response.usage.input_tokens,
    outputTokens: response.usage.output_tokens,
  };
}

async function scoreTask(context: string, task: EvalTask): Promise<CallResult> {
  const { answer, inputTokens, outputTokens } = await askWithContext(context, task.question);
  let totalInput = inputTokens;
  let totalOutput = outputTokens;

  let passed = false;

  if (task.requiredKeywords) {
    passed = checkKeywords(answer, task.requiredKeywords);
  } else if (task.judgePrompt) {
    const judge = await judgeAnswer(answer, task.judgePrompt);
    passed = judge.passed;
    totalInput += judge.inputTokens;
    totalOutput += judge.outputTokens;
  }

  return { answer, passed, inputTokens: totalInput, outputTokens: totalOutput };
}

// ── Report formatting ────────────────────────────────────────────────────────

function formatReport(
  results: TaskResult[],
  mainContextBytes: number,
  astContextBytes: number,
): string {
  const sep = "=".repeat(72);
  const lines: string[] = [];

  // Context sizes
  const mainTokensEst = estimateTokens(mainContext);
  const astTokensEst = estimateTokens(astContext);
  const sizeDelta = ((astContextBytes - mainContextBytes) / mainContextBytes * 100).toFixed(1);

  lines.push("");
  lines.push(sep);
  lines.push("  AST Parsing Experiment: A/B Eval Report");
  lines.push(sep);
  lines.push("");
  lines.push("  Context Sizes:");
  lines.push(`    Main (regex):       ${mainContextBytes.toLocaleString()} bytes  (~${mainTokensEst.toLocaleString()} tokens)`);
  lines.push(`    AST (tree-sitter):  ${astContextBytes.toLocaleString()} bytes  (~${astTokensEst.toLocaleString()} tokens)`);
  lines.push(`    Delta:              ${sizeDelta}%`);
  lines.push("");

  // Aggregate pass rates
  const mainPasses = results.filter((r) => r.main.passed).length;
  const astPasses = results.filter((r) => r.ast.passed).length;
  const total = results.length;
  const mainRate = mainPasses / total;
  const astRate = astPasses / total;
  const delta = astRate - mainRate;

  lines.push("  Pass Rates:");
  lines.push(`    Main:  ${mainPasses}/${total} (${(mainRate * 100).toFixed(1)}%)`);
  lines.push(`    AST:   ${astPasses}/${total} (${(astRate * 100).toFixed(1)}%)`);
  lines.push(`    Delta: ${delta >= 0 ? "+" : ""}${(delta * 100).toFixed(1)}%`);
  lines.push("");

  // Token usage
  const mainInputTotal = results.reduce((a, r) => a + r.main.inputTokens, 0);
  const mainOutputTotal = results.reduce((a, r) => a + r.main.outputTokens, 0);
  const astInputTotal = results.reduce((a, r) => a + r.ast.inputTokens, 0);
  const astOutputTotal = results.reduce((a, r) => a + r.ast.outputTokens, 0);
  const mainCost = costFromTokens(mainInputTotal, mainOutputTotal);
  const astCost = costFromTokens(astInputTotal, astOutputTotal);
  const totalCost = mainCost + astCost;

  lines.push("  Token Usage:");
  lines.push(`    Main:  ${mainInputTotal.toLocaleString()} in / ${mainOutputTotal.toLocaleString()} out  ($${mainCost.toFixed(3)})`);
  lines.push(`    AST:   ${astInputTotal.toLocaleString()} in / ${astOutputTotal.toLocaleString()} out  ($${astCost.toFixed(3)})`);
  lines.push(`    Total: $${totalCost.toFixed(3)}`);
  lines.push("");

  // Per-category breakdown
  const categories = [...new Set(TASKS.map((t) => t.category))];
  lines.push("  Per-Category:");
  lines.push(`    ${"Category".padEnd(22)} ${"Main".padEnd(10)} ${"AST".padEnd(10)} Delta`);
  lines.push(`    ${"-".repeat(56)}`);
  for (const cat of categories) {
    const catResults = results.filter((r) => r.category === cat);
    const catMain = catResults.filter((r) => r.main.passed).length;
    const catAst = catResults.filter((r) => r.ast.passed).length;
    const catTotal = catResults.length;
    const catDelta = catAst - catMain;
    const deltaStr = catDelta === 0 ? "  0" : catDelta > 0 ? ` +${catDelta}` : ` ${catDelta}`;
    lines.push(
      `    ${cat.padEnd(22)} ${catMain}/${catTotal}`.padEnd(36) +
      `${catAst}/${catTotal}`.padEnd(10) +
      deltaStr,
    );
  }
  lines.push("");

  // Per-task detail (across all iterations)
  lines.push("  Per-Task Detail:");
  lines.push(`    ${"Task".padEnd(10)} ${"Cat".padEnd(18)} ${"Iter".padEnd(6)} ${"Main".padEnd(8)} ${"AST".padEnd(8)} Flip`);
  lines.push(`    ${"-".repeat(60)}`);
  for (const r of results) {
    const mainStr = r.main.passed ? "PASS" : "FAIL";
    const astStr = r.ast.passed ? "PASS" : "FAIL";
    let flip = "  -";
    if (r.main.passed && !r.ast.passed) flip = "  REGRESS";
    else if (!r.main.passed && r.ast.passed) flip = "  IMPROVE";
    lines.push(
      `    ${r.taskId.padEnd(10)} ${r.category.padEnd(18)} ${String(r.iteration + 1).padEnd(6)} ${mainStr.padEnd(8)} ${astStr.padEnd(8)}${flip}`,
    );
  }
  lines.push("");

  // Verdict
  const nonInferior = delta >= -0.10;
  lines.push(`  Verdict: ${nonInferior ? "PASS" : "FAIL"} (non-inferiority gate: delta >= -10%)`);
  lines.push(sep);

  return lines.join("\n");
}

// ── Test ─────────────────────────────────────────────────────────────────────

describe.skipIf(SKIP)("AST A/B Eval", () => {
  beforeAll(() => {
    client = new Anthropic();
    mainContext = readFileSync("/tmp/clarte-main-claude.md", "utf-8");
    astContext = readFileSync("/tmp/clarte-ast-claude.md", "utf-8");
  });

  it(`runs ${N_ITERS} iteration(s) of ${TASKS.length} tasks`, async () => {
    const results: TaskResult[] = [];

    for (let iter = 0; iter < N_ITERS; iter++) {
      console.log(`\n── Iteration ${iter + 1}/${N_ITERS} ──`);

      for (const task of TASKS) {
        const [mainResult, astResult] = await Promise.all([
          scoreTask(mainContext, task),
          scoreTask(astContext, task),
        ]);

        results.push({
          taskId: task.id,
          category: task.category,
          iteration: iter,
          main: mainResult,
          ast: astResult,
        });

        const mIcon = mainResult.passed ? "PASS" : "FAIL";
        const aIcon = astResult.passed ? "PASS" : "FAIL";
        const mTok = `${mainResult.inputTokens}/${mainResult.outputTokens}`;
        const aTok = `${astResult.inputTokens}/${astResult.outputTokens}`;
        console.log(`  ${task.id.padEnd(8)} main=${mIcon} (${mTok})  ast=${aIcon} (${aTok})`);
      }
    }

    // Report
    const report = formatReport(
      results,
      Buffer.byteLength(mainContext, "utf-8"),
      Buffer.byteLength(astContext, "utf-8"),
    );
    console.log(report);

    // Assertions
    const mainPasses = results.filter((r) => r.main.passed).length;
    const astPasses = results.filter((r) => r.ast.passed).length;
    const delta = (astPasses - mainPasses) / results.length;

    // Non-inferiority: AST should not regress more than 10%
    expect(delta).toBeGreaterThanOrEqual(-0.10);

    // No single category should lose more than 2 tasks
    const categories = [...new Set(TASKS.map((t) => t.category))];
    for (const cat of categories) {
      const catResults = results.filter((r) => r.category === cat);
      const catMainPass = catResults.filter((r) => r.main.passed).length;
      const catAstPass = catResults.filter((r) => r.ast.passed).length;
      const catDelta = catAstPass - catMainPass;
      expect(
        catDelta,
        `Category "${cat}" regressed by ${Math.abs(catDelta)} tasks`,
      ).toBeGreaterThanOrEqual(-2);
    }
  }, 600_000); // 10 min timeout
});
